def edad_valida(texto):
    try: n=int(texto)
    except ValueError: return None
    return n if 0<=n<=120 else None

text-roundtrip:
def guardar_y_leer(ruta,texto):
    with open(ruta,"w",encoding="utf-8") as f: f.write(texto)
    with open(ruta,encoding="utf-8") as f: return f.read()

