budget-summary:
def gastos_por_categoria(movimientos):
    salida={}
    for m in movimientos:
        if m["tipo"]=="gasto": salida[m["categoria"]]=salida.get(m["categoria"],0)+m["monto"]
    return {k:round(v,2) for k,v in salida.items()}

