def resumen(datos): return {"cantidad":len(datos),"suma":sum(datos),"promedio":sum(datos)/len(datos) if datos else 0}
def frecuencias(texto):
    from collections import Counter
    return dict(Counter(texto.lower().split()))

checkpoint-final:
def analizar(texto_json):
    import json
    try: datos=json.loads(texto_json)
    except json.JSONDecodeError: return None
    if not isinstance(datos,list) or any(type(n) not in (int,float) for n in datos): return None
    return {"cantidad":len(datos),"suma":sum(datos)}
